  ('d653a893-a36a-58d7-9044-4027751958d3', null, (select id from public.skills where slug = 'write-g12-narrative-writing'), null, 'medium',
   $q$How do the short fragments in sentences 7, 8, and 9 affect the pacing of the narrative?$q$, $q$[{"text":"They shift the point of view so the reader sees the tray through Jun's eyes.","is_correct":false,"misconception_token":"false-pov-shift"},{"text":"They are grammatical errors that should be combined into one long sentence.","is_correct":false,"misconception_token":"treats-style-as-error"},{"text":"They reveal the disappointing catch one item at a time, matching the narrator's letdown.","is_correct":true},{"text":"They speed past the first sample so the reader does not notice it happened.","is_correct":false,"misconception_token":"misreads-pacing-speed"}]$q$::jsonb, $q$They reveal the disappointing catch one item at a time, matching the narrator's letdown.$q$, $q$Listing mud, a leaf, and one snail as separate beats makes the reader feel the empty tray slowly, the way the narrator does. The fragments are a deliberate stylistic choice, not errors to be fixed.$q$, 'draft', '45ab10b5-fea1-5c1f-9c7a-06ea5df02e70')
