  ('6f20cfb5-d923-5242-aa2e-a83c0ec163d7', null, (select id from public.skills where slug = 'data-statistics'), null, 'medium',
   $q$Daily sales at two stores are summarized. Store A: minimum 10, first quartile 15, median 22, third quartile 30, maximum 41. Store B: minimum 8, first quartile 19, median 24, third quartile 27, maximum 50. Which statement is true?$q$, $q$[{"text":"Store B has the greater median and the smaller IQR.","is_correct":true},{"text":"Store A has the greater median and the smaller IQR.","is_correct":false,"misconception_token":"reversed-the-comparison"},{"text":"Store A has the greater median and the greater IQR.","is_correct":false,"misconception_token":"misread-five-number-summary"},{"text":"Store B has the greater median and the greater IQR.","is_correct":false,"misconception_token":"used-range-for-spread"}]$q$::jsonb, $q$Store B has the greater median and the smaller IQR.$q$, $q$The medians are $22$ for Store A and $24$ for Store B, so Store B's is greater. The IQRs are $30 - 15 = 15$ for Store A and $27 - 19 = 8$ for Store B, so Store B's middle half is narrower. Store B does have the greater range, $50 - 8 = 42$, but the range is not the IQR.$q$, 'draft', null)
